      SUBROUTINE FRING2CC     CALCULATES SECOND-ORDER FRINGE FIELD TRANSFER MATRIXC      INCLUDE 'ELM2A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'T.CIN'CC     LOCAL VARIABLESC      REAL           EPS, SB2, SB3, TB2, TB3C-------------------------------------------------------------------------------C      EPS = 2.0*H0*APB(2)      TB2 = TB**2      TB3 = TB2*TB      SB2 = SB**2      SB3 = SB2*SB      IF (.NOT. BEFORE) GO TO 10CC     ENTRANCE FRINGE FIELDC      T(1,1) = - 0.5*H0*TB2      T(1,6) = 0.5*H0*(SB2     1       - EPS*LAYL*SB*TB*(5.0*SB2 + TB2))      T(2,1) = 0.5*H0*RABT*SB3 - H0**2*NB*TB      T(2,2) = H0*TB2      T(2,6) = H0**2*(TB*(NB + 0.5 + TB2)     1       - 0.5*EPS*LAYL*SB*TB2*(7.0*SB2 + 3.0*TB2))     2       - 0.5*H0*RABT*(SB3     3       - EPS*LAYL*TB*SB2*(5.0*SB2 + TB2))      T(2,9) = H0*( - TB2     1       + EPS*LAYL*SB*TB*(SB2 + TB2))      T(2,16) = - H0*TB      T(3,4) = H0*(TB2     1       - EPS*LAYL*SB*TB*(SB2 + TB2))      T(4,4) = 2.0*H0**2*TB*NB     1       - H0*RABT*(SB3 - EPS*LAYL*TB*SB2*(5.0*SB2 + TB2))      T(4,5) = H0*( - SB2     1       + EPS*LAYL*SB*TB*(5.0*SB2 + TB2))      T(4,7) = H0*( - TB2     1       + EPS*LAYL*SB*TB*(SB2 + TB2))      T(4,18) = H0*(TB     1        - 2.0*EPS*LAYL*SB*(SB2 + TB2))      GO TO 100CC     EXIT FRINGE FIELDC   10 T(1,1) = 0.5*H0*TB2      T(1,6) = 0.5*H0*( - SB2     1       + EPS*LAYL*SB*TB*(5.0*SB2 + TB2))      T(2,1) = 0.5*H0*RABT*SB3 - TB*(NB + 0.5*TB2)*H0**2      T(2,2) = - H0*TB2      T(2,6) = H0**2*(NB*TB - 0.5*TB3     1       + EPS*LAYL*SB*TB2*(SB2 + TB2))     2       - 0.5*H0*RABT*(SB3     3       - EPS*LAYL*TB*SB2*(5.0*SB2 + TB2))      T(2,9) = H0*(TB2     1       - EPS*LAYL*SB*TB*(SB2 + TB2))      T(2,16) = - H0*TB      T(3,4) = - H0*(TB2     1       - EPS*LAYL*SB*TB*(SB2 + TB2))      T(4,4) = H0**2*(TB*(2.0*NB + SB2)     1       - EPS*LAYL*SB*TB2*(5.0*SB2 + TB2))     2       - H0*RABT*(SB3 - EPS*LAYL*TB*SB2*(5.0*SB2 + TB2))      T(4,5) = H0*(SB2     1       - EPS*LAYL*SB*TB*(5.0*SB2 + TB2))      T(4,7) = H0*(TB2     1       - EPS*LAYL*SB*TB*(SB2 + TB2))      T(4,18) = H0*(TB     1        - 2.0*EPS*LAYL*SB*(SB2 + TB2))C 100  RETURN      END